def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    wall = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 2]
    if not wall:
        return out
    wall_rows = {r for r, c in wall}
    wall_cols = {c for r, c in wall}
    if len(wall_rows) == 1:
        horizontal, axis = True, next(iter(wall_rows))
    elif len(wall_cols) == 1:
        horizontal, axis = False, next(iter(wall_cols))
    else:
        return out

    counts = Counter(v for row in out for v in row if v != 2)
    background = counts.most_common(1)[0][0]
    colors = [v for row in out for v in row if v not in (2, background)]
    if not colors:
        return out
    color = Counter(colors).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if out[r][c] == color]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)

    if horizontal:
        if r1 < axis:
            shift = axis - 1 - r1
            moved = [(r + shift, c) for r, c in points]
            stripe = min(r for r, c in moved) - 1
        elif r0 > axis:
            shift = axis + 1 - r0
            moved = [(r + shift, c) for r, c in points]
            stripe = max(r for r, c in moved) + 1
        else:
            return out
        if not all(0 <= r < h for r, c in moved) or not 0 <= stripe < h:
            return out
    else:
        if c1 < axis:
            shift = axis - 1 - c1
            moved = [(r, c + shift) for r, c in points]
            stripe = min(c for r, c in moved) - 1
        elif c0 > axis:
            shift = axis + 1 - c0
            moved = [(r, c + shift) for r, c in points]
            stripe = max(c for r, c in moved) + 1
        else:
            return out
        if not all(0 <= c < w for r, c in moved) or not 0 <= stripe < w:
            return out

    for r, c in points:
        out[r][c] = background
    for r, c in moved:
        out[r][c] = color
    if horizontal:
        for c in range(w):
            out[stripe][c] = 8
    else:
        for r in range(h):
            out[r][stripe] = 8
    return out


if __name__ == "__main__":
